import { useEffect, useState } from "react";
import { fetchProducts, useAuthDispatch, useAuthState } from "../auth";

const pollingInterval = 2_500;
const maxPollingTime = 60_000;

/**
 * Hook that will poll for the latest order to appear in the auth state, if we are logged in.
 * Should be used inside an AuthAware component if you want to automatically check for the user's current login status.
 */
export const usePollForOrderInAuth = (orderId: number | undefined) => {
  const [isFetchingLatestOrder, setIsFetchingLatestOrder] = useState(true);
  const auth = useAuthState();
  const dispatch = useAuthDispatch();

  useEffect(() => {
    // Should wait until we know the order and have fetched the session/products at least once
    if (!orderId || !dispatch || auth.isFetchingSession || (auth.isLoggedIn && !auth.productsFetched)) {
      setIsFetchingLatestOrder(true);
      return undefined;
    }

    // If we are not logged in or already have the order, we are done
    if (!auth.isLoggedIn || auth.products?.webOrders.some((o) => o.no === orderId)) {
      setIsFetchingLatestOrder(false);
      return undefined;
    }

    setIsFetchingLatestOrder(true);
    const intervalId = setInterval(() => fetchProducts(dispatch), pollingInterval);
    const timeoutId = setTimeout(() => {
      clearInterval(intervalId);
      setIsFetchingLatestOrder(false);
    }, maxPollingTime);
    return () => {
      clearInterval(intervalId);
      clearTimeout(timeoutId);
    };
    // auth.webOrders is intentionally reached via the string of joined order ID:s, since it would otherwise trigger on every fetchProducts's completion
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    orderId,
    dispatch,
    auth.isFetchingSession,
    auth.isLoggedIn,
    auth.productsFetched,
    // eslint-disable-next-line react-hooks/exhaustive-deps
    auth.products?.webOrders.map((o) => o.no).join(";"),
  ]);

  return isFetchingLatestOrder;
};
