import DateHelper, { DateSource } from "./date-helper";

class LocalStorageHelper {
  isLocalStorageAvailable() {
    try {
      localStorage.isAvailable = true;
    } catch (e) {
      return false;
    }

    const isBrowser = typeof window !== "undefined";
    return isBrowser;
  }

  setItem(key: string, value: any, timestamp: DateSource) {
    if (!this.isLocalStorageAvailable()) {
      return;
    }

    if (!key || !value) {
      return;
    }

    if (timestamp) {
      value = { value: value, localStorageItemValidUntil: timestamp };
    }

    if (typeof value === "object") {
      value = JSON.stringify(value);
    }

    try {
      localStorage.setItem(key, value);
      return null;
    } catch (e) {
      console.error(`Error setting localStorage item for key "${key}":`, e);
      return e;
    }
  }

  isTimeStampValid(timestamp: number) {
    return !DateHelper.hasDatePassed(timestamp);
  }

  getItem(key: string) {
    if (!this.isLocalStorageAvailable()) {
      return undefined;
    }

    let value: any = localStorage.getItem(key);

    if (!value) {
      return undefined;
    }
    if (value[0] === "{" || value[0] === "[") {
      try {
        value = JSON.parse(value);
      } catch (e) {
        console.error(`Error parsing localStorage item for key "${key}":`, e);
        return undefined;
      }
    }

    if (value && !value.localStorageItemValidUntil) {
      return value;
    }

    return this.valueTimeStampValidation(value, key);
  }

  getValidUntilTimeStamp(key: string) {
    if (!this.isLocalStorageAvailable()) {
      return undefined;
    }

    let value: any = localStorage.getItem(key);

    if (!value) {
      return undefined;
    }
    if (value[0] === "{" || value[0] === "[") {
      value = JSON.parse(value);
    }

    if (value && !value.localStorageItemValidUntil) {
      return undefined;
    }

    return value.localStorageItemValidUntil as DateSource;
  }

  valueTimeStampValidation(value: { localStorageItemValidUntil: number; value: any }, key: string) {
    if (this.isTimeStampValid(value.localStorageItemValidUntil)) {
      return value.value;
    } else {
      this.removeItem(key);
      return undefined;
    }
  }

  removeItem(key: string) {
    if (!this.isLocalStorageAvailable()) {
      return;
    }
    localStorage.removeItem(key);
  }
}

const singleton = new LocalStorageHelper();
export default singleton;
