import { ItemInCart } from "@/core/components/modules/cart/cart-item";
import { CartResponseV2, CartResponseV2CartItem } from "@parksandresorts/webapiproxy-types";
import { cartItemToItemInCart } from "@/core/helpers";
import { useTranslation } from "react-i18next";
import { useProducts } from "./product-hooks";

export const useCartItemsFromCartResponse = (
  /** cart items to transform. These are not always the entire `cart.cartItems` since we might want to use this function to transform only a subset
   * Like in group admission summary when we use it to transform only the existing cart items.
   */
  cartItems: Array<CartResponseV2CartItem> | undefined,
  cart: CartResponseV2 | undefined,
): Array<ItemInCart> | undefined => {
  const cartItemIds = cartItems?.map((item) => item.productId) ?? [];

  const { productsById } = useProducts(cartItemIds);
  const { t } = useTranslation();

  return cartItems?.map((item) =>
    cartItemToItemInCart(item, productsById, cart?.discountItems ?? [], cart?.redeemableValidationResults ?? [], t),
  );
};
